<?php
namespace App\Application\Carts\Services;
use App\Domain\Contracts\Repositories\CartRepositoryInterface;use App\Domain\Contracts\TransactionManagerInterface;use App\Domain\Models\Cart;use InvalidArgumentException;
class CartService{public function __construct(private readonly CartRepositoryInterface $repository,private readonly TransactionManagerInterface $transactions){}public function getForUser(int|string $userId):Cart{return $this->repository->getOrCreate((string)$userId);}public function add(int|string $userId,string $productId,?string $variantId,int $quantity):Cart{if($quantity<1)throw new InvalidArgumentException('الكمية يجب أن تكون أكبر من صفر.');return $this->transactions->run(fn()=> $this->repository->add($this->repository->getOrCreate((string)$userId),$productId,$variantId,$quantity));}public function update(Cart $cart,string $itemId,int $quantity):Cart{if($quantity<1)throw new InvalidArgumentException('الكمية يجب أن تكون أكبر من صفر.');return $this->transactions->run(fn()=> $this->repository->update($cart,$itemId,$quantity));}public function remove(Cart $cart,string $itemId):Cart{return $this->repository->remove($cart,$itemId);}public function clear(Cart $cart):void{$this->repository->clear($cart);}}
